return {npc03001={id="npc03001",dsc="他是万灵谷的长老何歧，他身穿一件素色长衫，总是眉头紧缩，手上好像在盘着什么。",sex="男",age=35,looks=18,showequip={},withCorpse=0},npc03002={id="npc03002",dsc="她是万灵教的一名弟子，奉命把守着附近。",sex="女",age=24,looks=20,showequip={},withCorpse=0},npc03003={id="npc03003",dsc="他一身黑衣黑帽，将浑身裹得严严实实，唯一露出的只有一双眼睛。他的眼中满是杀气，令人生畏。",sex="男",age=40,looks=15,showequip={},withCorpse=0},npc03004={id="npc03004",dsc="他是万灵谷的左护法沙千里，他身穿一件五彩锦衣，太阳穴高高隆起。",sex="男",age=35,looks=18,showequip={},withCorpse=0},npc03005={id="npc03005",dsc="她便是这一代的万灵谷谷主丁红蝶，她身穿粉红纱裙，美艳不可方物，手脚都穿戴着金银饰器，稍一活动，金银就发出的清脆的碰撞声音，十分好听。",sex="女",age=17,looks=25,showequip={},withCorpse=0},npc03006={id="npc03006",dsc="重光教教众，身上的衣装有些奇怪，手上拿着一把大刀。",sex="男",age=18,looks=18,showequip={},withCorpse=0},npc03007={id="npc03007",dsc="信空大师的三弟子，年纪轻轻，武艺便已尽得信空大师真传，平日主要负责传授寺中弟子武功。信空大师被害后，他困苦万分，誓要重光付出代价。",sex="男",age=25,looks=20,showequip={},withCorpse=0},npc03008={id="npc03008",dsc="此人是天龙寺中的武僧，身材魁梧，负责看护这处寺庙，一看就知道是一位武功高强的高手。",sex="男",age=33,looks=17,showequip={},withCorpse=0},npc03009={id="npc03009",dsc="负责每日打扫整理莲池的僧人，看起来年纪不大，眼中透着一股子清亮。",sex="男",age=15,looks=21,showequip={},withCorpse=0},npc03010={id="npc03010",dsc="他就是信玄大师，他佛法精深，武功也是极高，在大理境内都有着极高的威望。",sex="男",age=65,looks=20,showequip={},withCorpse=0},npc03011={id="npc03011",dsc="他是万灵谷的长老何歧，他身穿一件素色长衫，总是眉头紧缩，手上好像在盘着什么。",sex="男",age=35,looks=18,showequip={},withCorpse=0},npc03012={id="npc03012",dsc="他一身黑衣，将浑身裹得严严实实，动作粗犷打量着四周，眼中满是杀气，令人生畏。",sex="男",age=30,looks=14,showequip={},withCorpse=0},npc03013={id="npc03013",dsc="他就是雅布陀罗，雪山寺年轻一代的代表人物，身上衣衫被划破些许，还沾点血迹，只怕一路上遇袭不少。",sex="男",age=22,looks=19,showequip={},withCorpse=0},npc03014={id="npc03014",dsc="一名大理城内的收尸人，总是佝偻着背，身上扛着扁担和布袋。",sex="男",age=38,looks=17,showequip={},withCorpse=0},npc03015={id="npc03015",dsc="她是万灵教的一名弟子，眉眼清秀，神情严肃。",sex="女",age=21,looks=18,showequip={},withCorpse=0},npc03016={id="npc03016",dsc="他穿着一身天龙寺的衣服，但是身手有些奇怪，行为不似出家人。",sex="男",age=28,looks=16,showequip={},withCorpse=0},npc03017={id="npc03017",dsc="一名天龙寺的小僧，年纪不大但是很机灵，眼里有股子灵性的亮光。",sex="男",age=15,looks=22,showequip={},withCorpse=0},npc03018={id="npc03018",dsc="他穿着一身万灵教的服装，手中拿着武器，有点分辨不出男女。",sex="男",age=25,looks=16,showequip={},withCorpse=0},npc03019={id="npc03019",dsc="一名万灵教的弟子，眼神有些凶戾，正警惕的看着周围。",sex="男",age=25,looks=17,showequip={},withCorpse=0},npc03020={id="npc03020",dsc="他手上握着武器，一身穿着杂乱无章，脸上带着点不怀好意的笑容，审视着四周环境。",sex="男",age=25,looks=16,showequip={},withCorpse=0},npc03021={id="npc03021",dsc="他身上穿着一身布衣，腰背有些弯曲，皱着眉头时不时叹一口气。",sex="男",age=45,looks=18,showequip={},withCorpse=0},npc03022={id="npc03022",dsc="他是一名官府的仵作，协助破获大理城中多起大案，被奸人所害，关押在义庄已久，显得十分疲惫。",sex="男",age=33,looks=18,showequip={},withCorpse=0},npc03023={id="npc03023",dsc="他就是大理城中最厉害的机关师傅，教出数位精通机巧的弟子，本身的实力更是深不可测。",sex="男",age=55,looks=19,showequip={},withCorpse=0},npc03024={id="npc03024",dsc="他是天龙寺的一个小沙弥，日常干着打扫莲池的活计。",sex="男",age=12,looks=20,showequip={},withCorpse=0},npc03025={id="npc03025",dsc="他是一名天龙寺的弟子，身上衣服有些破损，看样子被折磨了许久。",sex="男",age=24,looks=19,showequip={},withCorpse=0},npc03026={id="npc03026",dsc="他是重光十二使徒之一李胜贤，是来自高丽的一名天才少年刀客，手中常年握着一把云剑，每时每刻都审视着四周。",sex="男",age=32,looks=20,showequip={},withCorpse=0},npc03027={id="npc03027",dsc="他是重光十二使徒之一塞索斯，是一名来自大秦国的剑士，过去做为角斗士未尝一败，为人凶悍好斗，直来直去，十分难缠。",sex="男",age=40,looks=19,showequip={},withCorpse=0},npc03028={id="npc03028",dsc="一名卖杂货的小贩，常年走街串巷，对大理城十分熟悉。",sex="男",age=33,looks=17,showequip={},withCorpse=0},npc03029={id="npc03029",dsc="一身滑稽的服装，脸上画着花脸，手上耍着杂戏。",sex="男",age=29,looks=19,showequip={},withCorpse=0},npc03030={id="npc03030",dsc="她衣着朴素，手上纺着线，面色枯黄，眼里带着疲惫。",sex="女",age=35,looks=18,showequip={},withCorpse=0},npc03031={id="npc03031",dsc="看上去还不到十岁的小孩童，脸上挂着天真无邪的笑，身上穿着粗布衣裳，打着几个补丁。",sex="女",age=8,looks=20,showequip={},withCorpse=0},npc03032={id="npc03032",dsc="他穿着普通，手上提着个葫芦，身上一股子酒味，像在酒缸中泡过似的。",sex="男",age=42,looks=17,showequip={},withCorpse=0},npc03033={id="npc03033",dsc="一名大理城内的银匠，手艺十分精湛，大理城中哪家要打银饰都会来找他。",sex="男",age=35,looks=18,showequip={},withCorpse=0},npc03034={id="npc03034",dsc="他是天龙寺的一名弟子，身上穿着僧袍，手中拿着武器，时不时看向四周。",sex="男",age=25,looks=17,showequip={},withCorpse=0},npc03035={id="npc03035",dsc="他一身黑衣，将浑身裹得严严实实，动作粗犷打量着四周，眼中满是杀气，令人生畏。",sex="男",age=30,looks=16,showequip={},withCorpse=0},npc03036={id="npc03036",dsc="他面容阴鸷凶悍，行事狠戾不择手段，为达目的肆意妄为，是江湖中人人忌惮的恶徒之流。",sex="男",age=28,looks=18,showequip={},withCorpse=0}}000000000000000